export const objectives=[4,10,40,100];
export const clamp=(n,min,max)=>Math.min(max,Math.max(min,n));
export function opticalState({objective=10,coarse=43,fine=0,light=68,iris=60,oil=false}={}){
 objective=objectives.includes(Number(objective))?Number(objective):10;
 const targetFine=objective===100?.9:objective===40?.5:0;
 const error=Math.abs((coarse-52)*.32+fine-targetFine);
 const blur=clamp(error*(objective>=40?1.9:1.15),0,13);
 return {objective,total:objective*10,field:18000/objective,blur,sharpness:Math.round(clamp(100-error*22,0,100)),brightness:clamp(light/68,.04,1.5),contrast:.8+iris/200,coarseLocked:objective>=40,oilRequired:objective===100&&!oil};
}
export function scaleBar(field){const target=field/5;const value=[5,10,20,50,100,200,500,1000].filter(x=>x<=target).at(-1)||5;return {value,fraction:value/field}}
